head.script:
/************************** 
 * 이슈리스크 관리 시스템 JavaScript
 * 작성일: 2025.07.17
 * 기능: 이슈/리스크 CRUD, 파일 관리, 상태별 분류 등
 **************************/

/************************** 1. 페이지 초기화 및 기본 설정 *************************/

scwin.currentMode = "list"; // "list", "new", "edit", "view"

// 사용자 및 프로젝트 정보 전역 변수
scwin.USER_ID = "";
scwin.USER_NAME = "";
scwin.SELECTED_PROJECT_ID = "";
scwin.GROUP_ID = "";
scwin.SELECTED_PROJECT_NAME = "";

/**
 * 페이지 로드 시 초기화
 */
scwin.onpageload = function () {
    console.log("=== 이슈 페이지 로드 ===");

    // 헤더에서 사용자 정보만 한 번 가져오기
    var headerWindow = $p.getComponentById("mf_pg_header");
    if (headerWindow) {
        scwin.USER_ID = headerWindow.getWindow().scwin.USER_ID;
        scwin.USER_NAME = headerWindow.getWindow().scwin.USER_NAME;
    }

    // 버튼 초기화
    btn_save.show("");
    btn_edit.hide();
    btn_delete.hide();

    // 페이지 정보 초기화
    scwin.initPaginationInfo();

    // 검색박스 표시/숨김 처리
    var cptIbxName = $p.getComponentById("searchComp_1");
    if (cptIbxName == undefined) {
        search_box.hide();
    }

    // 초기 데이터 조회 (이때 최신 프로젝트 정보 가져옴)
    scwin.btn_search_onclick();
};

/**
 * 새로고침 버튼에도 동일 로직 적용
 */
scwin.btn_refresh_project_onclick = function(e) {
    console.log("=== 프로젝트 새로고침 ===");
    scwin.btn_search_onclick(); // 최신 프로젝트 정보로 다시 조회
};

/**
 * 각 그리드별 페이지 정보 초기화
 */
scwin.initPaginationInfo = function () {
    console.log("페이지 정보 초기화 시작");

    // 전체 데이터 페이지 정보
    scwin.allDataPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 대기 데이터 페이지 정보
    scwin.waitingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 진행중 데이터 페이지 정보
    scwin.processingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 완료 데이터 페이지 정보
    scwin.completedPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };
};

/************************** 2. 공통 유틸리티 함수 *************************/

/**
 * 페이지별 데이터 분할 함수
 * @param {Array} data - 전체 데이터 배열
 * @param {Object} pageInfo - 페이지 정보 객체
 * @returns {Array} 분할된 데이터 배열
 */
scwin.getPageData = function (data, pageInfo) {
    if (!data || !pageInfo) {
        console.error("getPageData: 데이터 또는 페이지 정보가 없습니다.");
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

/**
 * 페이지 네비게이터 업데이트 함수
 * @param {Object} pageInfo - 페이지 정보
 * @param {Object} paginationComponent - 페이지네이션 컴포넌트
 */
scwin.updatePagination = function (pageInfo, paginationComponent) {
    if (!pageInfo || !paginationComponent) {
        console.error("updatePagination: 페이지 정보 또는 컴포넌트가 없습니다.");
        return;
    }

    var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
    if (totalPages > 0) {
        paginationComponent.setCount(totalPages);
        paginationComponent.setSelectedIndex(pageInfo.currentPage);
    }
};

/**
 * 공통 오류 처리 함수
 * @param {string} operation - 작업명
 * @param {Object} error - 오류 객체
 * @param {boolean} showAlert - 알림 표시 여부
 * @returns {string} 오류 메시지
 */
scwin.handleError = function(operation, error, showAlert) {
    showAlert = showAlert !== false; // 기본값 true

    var errorMsg = operation + "에 실패했습니다.";
    if (error && error.message) {
        errorMsg += "\n상세 오류: " + error.message;
    }

    console.error(operation + " 오류:", error);

    if (showAlert) {
        $c.win.alert(errorMsg);
    }

    return errorMsg;
};

/**
 * HTML 태그 제거 함수
 * @param {string} htmlString - HTML 문자열
 * @returns {string} 텍스트만 추출된 문자열
 */
scwin.stripHtmlTags = function(htmlString) {
    if (!htmlString) return "";

    // HTML 태그 제거
    var text = htmlString.replace(/<[^>]*>/g, "");

    // HTML 엔티티 디코딩
    text = text.replace(/&nbsp;/g, " ");
    text = text.replace(/&lt;/g, "<");
    text = text.replace(/&gt;/g, ">");
    text = text.replace(/&amp;/g, "&");
    text = text.replace(/&quot;/g, '"');

    // 여러 개의 공백이나 줄바꿈을 하나로 정리
    text = text.replace(/\s+/g, " ").trim();

    return text;
};

/************************** 3. 데이터 조회 관련 함수 *************************/

/**
 * 조회 버튼 클릭 이벤트
 */
scwin.btn_search_onclick = function (e) {
    console.log("=== 검색 시작 ===");

    // 헤더에서 직접 현재 선택된 값 가져오기
    var headerWindow = $p.getComponentById("mf_pg_header");
    if (headerWindow) {
        var headerScwin = headerWindow.getWindow();
        if (headerScwin && headerScwin.selectBoxProjectName) {
            var currentSelectedProject = headerScwin.selectBoxProjectName.getValue();
            console.log("헤더에서 직접 가져온 프로젝트 ID:", currentSelectedProject);

            if (currentSelectedProject) {
                scwin.SELECTED_PROJECT_ID = currentSelectedProject;

                // 프로젝트명도 가져오기
                var projectList = headerScwin.dlt_projectName;
                if (projectList) {
                    var projectName = projectList.getMatchedColumnData("pjtId", currentSelectedProject, "pjtName");
                    scwin.SELECTED_PROJECT_NAME = projectName;
                    console.log("프로젝트명:", scwin.SELECTED_PROJECT_NAME);
                }
            }
        }
    }
    // 부모 윈도우 정보와 비교
    var parentWindow = $p.getParentWindow();
    if (parentWindow && parentWindow.scwin) {
        console.log("부모 윈도우 프로젝트 ID:", parentWindow.scwin.SEL_PJT_ID);
        console.log("헤더에서 가져온 프로젝트 ID:", scwin.SELECTED_PROJECT_ID);

        // 둘 중 더 최신 정보 사용 (헤더가 더 정확할 가능성 높음)
        if (!scwin.SELECTED_PROJECT_ID && parentWindow.scwin.SEL_PJT_ID) {
            scwin.SELECTED_PROJECT_ID = parentWindow.scwin.SEL_PJT_ID;
        }
    }

    console.log("최종 사용할 프로젝트 ID:", scwin.SELECTED_PROJECT_ID);

    if (!scwin.waitingPageInfo) {
        scwin.initPaginationInfo();
    }

    // 프로젝트가 선택되지 않은 경우
    if (!scwin.SELECTED_PROJECT_ID) {
        console.log("프로젝트가 선택되지 않았습니다.");
        // 데이터 초기화
        dlt_waitingList.setJSON([]);
        dlt_processingList.setJSON([]);
        dlt_completedList.setJSON([]);
        scwin.updateCountLabels(0, 0, 0, 0);
        return;
    }

    // 검색 조건 설정 (최신 프로젝트 정보로)
    dmp_issVo.set("pageIndex", "1");
    dmp_issVo.set("pageSize", "1000");
    dmp_issVo.set("pjtId", scwin.SELECTED_PROJECT_ID);
    dmp_issVo.set("userId", scwin.USER_ID);

    console.log("검색 조건:", {
        pjtId: scwin.SELECTED_PROJECT_ID,
        userId: scwin.USER_ID,
        pageIndex: "1",
        pageSize: "1000"
    });

    $c.sbm.execute($p, sbm_selectIssVoList);
};

/**
 * 서버 조회 결과 처리 콜백
 * @param {Object} e - 서버 응답 이벤트 객체
 */
scwin.sbm_issList_submitdone = function (e) {
    console.log("서버 응답 수신", e);

    if (!scwin.allDataPageInfo) {
        scwin.initPaginationInfo();
    }

    var elData = e.responseJSON ? e.responseJSON.elData : null;
    var elHeader = e.responseJSON ? e.responseJSON.elHeader : null;

    // 응답 성공 여부 확인
    if (!elHeader || elHeader.resSuc !== true) {
        var errorMsg = "데이터 조회에 실패했습니다.";
        if (elHeader && elHeader.resMsg) {
            errorMsg += "\n오류메시지: " + elHeader.resMsg;
        }
        if (elHeader && elHeader.resCode) {
            errorMsg += "\n오류코드: " + elHeader.resCode;
        }
        $c.win.alert(errorMsg);
        return false;
    }

    // 성공 시 데이터 처리
    var allData = elData.issVoList || [];
    console.log("전체 데이터:", allData.length, "개");

    scwin.allDataPageInfo.data = allData;
    scwin.allDataPageInfo.totalCount = elData.totalCount;

    // 상태별로 데이터 필터링
    var waitingData = [];      // 대기 (PEN)
    var processingData = [];   // 진행중 (IPR)
    var completedData = [];    // 완료 (COM)

    for (var i = 0; i < allData.length; i++) {
        var item = allData[i];
        if (item.status === "PEN") {
            waitingData.push(item);
        } else if (item.status === "IPR") {
            processingData.push(item);
        } else if (item.status === "COM") {
            completedData.push(item);
        }
    }

    // 각 그리드별 데이터 저장
    scwin.waitingPageInfo.data = waitingData;
    scwin.waitingPageInfo.totalCount = waitingData.length;
    scwin.waitingPageInfo.currentPage = 1;

    scwin.processingPageInfo.data = processingData;
    scwin.processingPageInfo.totalCount = processingData.length;
    scwin.processingPageInfo.currentPage = 1;

    scwin.completedPageInfo.data = completedData;
    scwin.completedPageInfo.totalCount = completedData.length;
    scwin.completedPageInfo.currentPage = 1;

    // 그리드 및 UI 업데이트
    scwin.updateGridData();
    scwin.updatePaginationAll(elData.totalCount);
    scwin.updateCountLabels(waitingData.length, processingData.length, completedData.length, elData.totalCount);

    // 폼 초기화
    dmp_issVoDetail.setEmptyValue();
};

/**
 * 조회 오류 처리 콜백
 */
scwin.sbm_issList_submiterror = function(e) {
    scwin.handleError("데이터 조회", e);
};

/**
 * 각 그리드 데이터 업데이트
 */
scwin.updateGridData = function () {
    console.log("그리드 데이터 업데이트 시작");

    try {
        // 전체 데이터 그리드 (첫 페이지만 표시)
        if (scwin.allDataPageInfo && scwin.allDataPageInfo.data) {
            var allPageData = scwin.allDataPageInfo.data.slice(0, 10);
            dlt_issVoList.setJSON(allPageData);
        }

        // 대기 그리드
        if (scwin.waitingPageInfo && scwin.waitingPageInfo.data) {
            var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
            dlt_waitingList.setJSON(waitingPageData);
        }

        // 진행중 그리드
        if (scwin.processingPageInfo && scwin.processingPageInfo.data) {
            var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
            dlt_processingList.setJSON(processingPageData);
        }

        // 완료 그리드
        if (scwin.completedPageInfo && scwin.completedPageInfo.data) {
            var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
            dlt_completedList.setJSON(completedPageData);
        }
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/**
 * 전체 페이지네이션 업데이트
 * @param {number} totalCount - 전체 데이터 수
 */
scwin.updatePaginationAll = function(totalCount) {
    var serverPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: totalCount
    };

    scwin.updatePagination(serverPageInfo, pgl_issList);
    scwin.updatePagination(scwin.waitingPageInfo, pgl_waiting);
    scwin.updatePagination(scwin.processingPageInfo, pgl_processing);
    scwin.updatePagination(scwin.completedPageInfo, pgl_com);
};

/**
 * 카운트 라벨 업데이트
 * @param {number} waitingCount - 대기 건수
 * @param {number} processingCount - 진행중 건수
 * @param {number} completedCount - 완료 건수
 * @param {number} totalCount - 전체 건수
 */
scwin.updateCountLabels = function(waitingCount, processingCount, completedCount, totalCount) {
    spn_waitListCnt.setLabel(waitingCount);
    spn_processingListCnt.setLabel(processingCount);
    spn_completeListCnt.setLabel(completedCount);
    spn_listCnt.setLabel(totalCount);
};

/************************** 4. 페이지네이션 이벤트 *************************/

/**
 * 전체 데이터 페이지 클릭
 * @param {number} idx - 페이지 인덱스
 */
scwin.pgl_issList_onclick = function (idx) {
    dmp_issVo.set("pageIndex", idx);
    dmp_issVo.set("pageSize", "10");
    $c.sbm.execute($p, sbm_selectIssVoList);
};

/**
 * 대기 데이터 페이지 클릭
 * @param {number} idx - 페이지 인덱스
 */
scwin.pgl_waiting_onclick = function (idx) {
    if (!scwin.waitingPageInfo) return;

    scwin.waitingPageInfo.currentPage = idx;
    var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
    dlt_waitingList.setJSON(waitingPageData);
    pgl_waiting.setSelectedIndex(idx);
};

/**
 * 진행중 데이터 페이지 클릭
 * @param {number} idx - 페이지 인덱스
 */
scwin.pgl_processing_onclick = function (idx) {
    if (!scwin.processingPageInfo) return;

    scwin.processingPageInfo.currentPage = idx;
    var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
    dlt_processingList.setJSON(processingPageData);
    pgl_processing.setSelectedIndex(idx);
};

/**
 * 완료 데이터 페이지 클릭
 * @param {number} idx - 페이지 인덱스
 */
scwin.pgl_com_onclick = function (idx) {
    if (!scwin.completedPageInfo) return;

    scwin.completedPageInfo.currentPage = idx;
    var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
    dlt_completedList.setJSON(completedPageData);
    pgl_com.setSelectedIndex(idx);
};

/************************** 5. 그리드 이벤트 *************************/

/**
 * 전체 그리드 셀 클릭 이벤트
 * @param {number} row - 행 인덱스
 * @param {number} col - 열 인덱스  
 * @param {string} colId - 열 ID
 */
scwin.grd_list_oncellclick = function (row, col, colId) {
    dmp_issVoDetail.setJSON(dlt_issVoList.getRowJSON(row));

    // 버튼 상태 변경 (조회 모드)
    btn_save.hide();
    btn_edit.show("");
    btn_delete.show("");
};

/**
 * 대기 그리드 더블클릭 - 상세보기 팝업
 * @param {number} rowIndex - 행 인덱스
 * @param {number} columnIndex - 열 인덱스
 * @param {string} columnId - 열 ID
 */
scwin.waiting_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_waitingList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("대기 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("대기 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

/**
 * 진행중 그리드 더블클릭 - 상세보기 팝업
 */
scwin.processing_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_processingList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("진행중 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("진행중 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

/**
 * 완료 그리드 더블클릭 - 상세보기 팝업
 */
scwin.complete_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_completedList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("완료 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("완료 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

/************************** 6. 폼 모드 및 UI 제어 *************************/

/**
 * 폼 모드 설정 함수
 * @param {string} mode - 모드 ('new', 'edit', 'view')
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);
    scwin.currentMode = mode; // 현재 모드 저장

    if (mode === "edit") {
        // 수정 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 수정 모드에서는 상태 선택 가능
        sel_status.setDisabled(false);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.setEditorMode(false);
        scwin.showFileUploadSection(false);

        // 조회 모드에서는 상태 선택 불가
        sel_status.setDisabled(true);

        // 버튼 상태 변경
        btn_save.hide();
        btn_popup_edit.show();

    } else if (mode === "new") {
        // 등록 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 등록 모드에서는 상태를 대기로 고정하고 선택 불가
        sel_status.setValue("PEN");
        sel_status.setDisabled(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();
        btn_popup_delete.hide();
    }
};

/**
 * 필드 읽기 전용 설정
 * @param {boolean} readOnly - 읽기 전용 여부
 */
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        // 편집 가능한 필드들 (상태 제외)
        var editableFields = [
            "inp_issueName",     // 이슈/리스크명
            "sel_priority",      // 우선순위
            "cal_dueDate",       // 완료예정일
            "cal_resolvedDate"   // 해결일
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 프로젝트명과 담당자명은 항상 readOnly
        var alwaysReadOnlyFields = ["inp_projectName", "inp_userName"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 파일 업로드 섹션 표시/숨김
 * @param {boolean} show - 표시 여부
 */
scwin.showFileUploadSection = function(show) {
    try {
        if (show) {
            grp_fileUploadArea.show();
        } else {
            grp_fileUploadArea.hide();
        }
    } catch(e) {
        console.error("파일 업로드 섹션 표시 오류:", e);
