};

/************************** 7. 에디터 관련 함수 *************************/

/**
 * 에디터 모드 전환 함수
 * @param {boolean} isEditMode - 편집 모드 여부
 */
scwin.setEditorMode = function(isEditMode) {
    console.log("에디터 모드 전환:", isEditMode ? "편집" : "조회");

    if (isEditMode) {
        // 편집 모드: 에디터 표시
        var description = dmp_issVoDetail.get("description") || "";
        var responsePlan = dmp_issVoDetail.get("responsePlan") || "";

        try {
            editor_description.setText(description);
            editor_responsePlan.setText(responsePlan);
        } catch(e) {
            console.error("에디터 값 설정 오류:", e);
        }

        grp_description_edit.show();
        grp_description_view.hide();
        grp_response_edit.show();
        grp_response_view.hide();
    } else {
        // 조회 모드: HTML 렌더링 표시
        grp_description_edit.hide();
        grp_description_view.show();
        grp_response_edit.hide();
        grp_response_view.show();

        scwin.updateViewContentWithHTML();
    }
};

/**
 * HTML 스타일을 포함한 내용 표시
 */
scwin.updateViewContentWithHTML = function() {
    try {
        var description = dmp_issVoDetail.get("description") || "";
        var responsePlan = dmp_issVoDetail.get("responsePlan") || "";

        // HTML을 div 요소에 직접 렌더링
        scwin.renderHTMLContent("div_description_view", description);
        scwin.renderHTMLContent("div_response_view", responsePlan);

    } catch(e) {
        console.error("HTML 내용 업데이트 실패:", e);
        // 오류 시 기존 방식으로 폴백
        scwin.updateViewContent();
    }
};

/**
 * HTML 내용을 안전하게 렌더링
 * @param {string} elementId - DOM 요소 ID
 * @param {string} htmlContent - HTML 내용
 */
scwin.renderHTMLContent = function(elementId, htmlContent) {
    try {
        // 빈 내용 처리
        if (!htmlContent || htmlContent.trim() === "") {
            htmlContent = "<p style='color: #999; font-style: italic;'>내용이 없습니다.</p>";
        }

        // DOM 요소 찾기
        var element = document.getElementById(elementId);
        if (!element) {
            console.warn("요소를 찾을 수 없습니다:", elementId);
            return;
        }

        // HTML 내용 설정 및 스타일 적용
        element.innerHTML = htmlContent;
        element.style.padding = "15px";
        element.style.border = "1px solid #ddd";
        element.style.borderRadius = "4px";
        element.style.backgroundColor = "#f9f9f9";
        element.style.minHeight = "100px";
        element.style.maxHeight = "300px";
        element.style.overflowY = "auto";
        element.style.lineHeight = "1.6";
        element.style.fontFamily = "inherit";

        console.log("HTML 내용 렌더링 완료:", elementId);

    } catch(e) {
        console.error("HTML 렌더링 오류:", e);
    }
};

/**
 * 조회 모드에서 HTML 내용을 텍스트로 변환 (폴백용)
 */
scwin.updateViewContent = function() {
    try {
        var description = dmp_issVoDetail.get("description") || "";
        var responsePlan = dmp_issVoDetail.get("responsePlan") || "";

        // HTML 태그 제거하고 텍스트만 추출
        var descriptionText = scwin.stripHtmlTags(description);
        var responsePlanText = scwin.stripHtmlTags(responsePlan);

        // 조회 영역에 설정
        txt_description_view.setValue(descriptionText);
        txt_response_view.setValue(responsePlanText);

    } catch(e) {
        console.error("내용 업데이트 실패:", e);
    }
};

/**
 * 에디터 내용 동기화
 * @returns {boolean} 동기화 성공 여부
 */
scwin.syncEditorContent = function() {
    try {
        var descriptionHTML = "";
        var responsePlanHTML = "";

        // 에디터에서 HTML 내용을 가져오기
        if (editor_description) {
            if (typeof editor_description.getHTML === 'function') {
                descriptionHTML = editor_description.getHTML();
            } else if (typeof editor_description.getValue === 'function') {
                descriptionHTML = editor_description.getValue();
            }
        }

        if (editor_responsePlan) {
            if (typeof editor_responsePlan.getHTML === 'function') {
                responsePlanHTML = editor_responsePlan.getHTML();
            } else if (typeof editor_responsePlan.getValue === 'function') {
                responsePlanHTML = editor_responsePlan.getValue();
            }
        }

        // 데이터맵에 HTML 내용 설정
        dmp_issVoDetail.set("description", descriptionHTML);
        dmp_issVoDetail.set("responsePlan", responsePlanHTML);

        console.log("에디터 내용 동기화 완료");
        console.log("상세설명 HTML 길이:", descriptionHTML.length);
        console.log("대응방안 HTML 길이:", responsePlanHTML.length);

        return true;

    } catch(e) {
        console.error("에디터 내용 동기화 오류:", e);
        return false;
    }
};

/**
 * 에디터 내용 변경 시 자동 동기화 - 상세설명
