    // 파일 관련 초기화
    dlt_upload.setJSON([]);
    dlt_FileList.setJSON([]);

    pop_overlay.show();
    scwin.setFormMode("new");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("이슈리스크 등록");
            sel_status.setValue("PEN");
            sel_status.setDisabled(true);
