/**
 * 저장 버튼 클릭 이벤트
 */
scwin.btn_save_onclick = function (e) {
    console.log("저장 버튼 클릭됨 - 현재 모드:", scwin.currentMode);

    // 에디터 포커스 해제하여 내용 확정
    try {
        if (editor_description && editor_description.blur) {
            editor_description.blur();
        }
        if (editor_responsePlan && editor_responsePlan.blur) {
            editor_responsePlan.blur();
        }
    } catch(e) {
        console.log("에디터 blur 실패, 무시");
    }

    // 잠시 대기 후 저장 실행 (에디터 내용 동기화 시간 확보)
    setTimeout(function() {
        var issueName = dmp_issVoDetail.get("name");
        if (!issueName || issueName.trim() === "") {
            $c.win.alert("이슈/리스크명을 입력해주세요.");
            return;
        }

        // 모드에 따라 다른 저장 로직 실행
        if (scwin.currentMode === "new") {
            scwin.sendIssueAndFiles(); // 등록
        } else if (scwin.currentMode === "edit") {
            scwin.updateIssueAndFiles(); // 수정
        } else {
            console.error("잘못된 모드:", scwin.currentMode);
        }
    }, 100);
};

/**
 * 이슈와 파일 전송 (등록용)
 */
scwin.sendIssueAndFiles = function () {
    console.log("sendIssueAndFiles() 시작됨");

    // 에디터 내용을 먼저 확실하게 동기화
    try {
        var descriptionHTML = "";
        var responsePlanHTML = "";

        // 에디터에서 HTML 내용 가져오기
        if (editor_description && typeof editor_description.getHTML === 'function') {
            descriptionHTML = editor_description.getHTML();
            console.log("상세설명 HTML:", descriptionHTML);
        }

        if (editor_responsePlan && typeof editor_responsePlan.getHTML === 'function') {
            responsePlanHTML = editor_responsePlan.getHTML();
            console.log("대응방안 HTML:", responsePlanHTML);
        }

        // 데이터맵에 HTML 내용 직접 설정
        dmp_issVoDetail.set("description", descriptionHTML);
        dmp_issVoDetail.set("responsePlan", responsePlanHTML);

    } catch(e) {
        console.error("에디터 내용 가져오기 실패:", e);
    }

    // FormData 생성 및 데이터 추가
    var formData = new FormData();
    formData.append("pjtId", dmp_issVoDetail.get("pjtId"));
    formData.append("name", dmp_issVoDetail.get("name"));
    formData.append("userId", dmp_issVoDetail.get("userId"));
    formData.append("dueDate", dmp_issVoDetail.get("dueDate"));
    formData.append("status", "PEN"); // 등록 시 상태를 무조건 대기(PEN)로 강제 설정
    formData.append("priority", dmp_issVoDetail.get("priority") || "MD");
    formData.append("description", dmp_issVoDetail.get("description") || "");
    formData.append("responsePlan", dmp_issVoDetail.get("responsePlan") || "");
    formData.append("resolvedDate", dmp_issVoDetail.get("resolvedDate"));

    // 파일 추가
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        console.log("fileList", fileList);

        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var realFile = fileList[i];
                console.log('real', realFile);
                formData.append("files", realFile);
            }
        }
    }

    // FormData 내용 확인 (디버깅용)
    console.log("=== FormData 내용 확인 ===");
    for (var pair of formData.entries()) {
        console.log(pair[0] + ': ' + (pair[1] instanceof File ? pair[1].name : pair[1]));
    }

    // 서버로 전송
    fetch("/InsWebApp/ISS001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { 
        if (!res.ok) {
            throw new Error('HTTP ' + res.status + ': ' + res.statusText);
        }
        return res.json(); 
    })
    .then(function(res) {
        console.log("서버 응답:", res);

        // 서버 응답 구조 확인 및 성공 여부 판단
        var elHeader = res.elHeader;

        if (elHeader && elHeader.resSuc === true) {
            // 성공인 경우
            $c.win.alert("등록되었습니다.");
            dlt_upload.removeAll();
            if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
                mpd_html5Type.removeAllFiles();
            }
            pop_overlay.hide();
            scwin.btn_search_onclick();
        } else {
            // 실패인 경우
            var errorMsg = "등록에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            $c.win.alert(errorMsg);
        }
    })
    .catch(function(err) {
        console.error("전송 실패:", err);
        var errorMsg = "등록 중 오류가 발생했습니다.";
        if (err.message) {
            errorMsg += "\n상세 오류: " + err.message;
        }
        $c.win.alert(errorMsg);
    });
};

/**
 * 수정 버튼 클릭 이벤트
 */
scwin.btn_edit_onclick = function (e) {
    var issueId = dmp_issVoDetail.get("id");
    var issueName = dmp_issVoDetail.get("name");

    if (!issueId || issueId.trim() === "") {
        $c.win.alert("이슈 ID가 없습니다.");
        return;
    }

    if (!issueName || issueName.trim() === "") {
        $c.win.alert("이슈/리스크명을 입력해주세요.");
        return;
    }

    // 수정 시에도 에디터 내용 동기화
    try {
        var descriptionHTML = "";
        var responsePlanHTML = "";

        if (editor_description && typeof editor_description.getHTML === 'function') {
            descriptionHTML = editor_description.getHTML();
            dmp_issVoDetail.set("description", descriptionHTML);
        }

        if (editor_responsePlan && typeof editor_responsePlan.getHTML === 'function') {
            responsePlanHTML = editor_responsePlan.getHTML();
            dmp_issVoDetail.set("responsePlan", responsePlanHTML);
        }

        console.log("수정 시 에디터 내용 동기화 완료");

    } catch(e) {
        console.error("수정 시 에디터 내용 동기화 실패:", e);
    }

    var promise = $c.win.confirm("수정하시겠습니까?");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_updateIssVo);
        } else {
            scwin.setFormMode("view");
        }
    });
};

