};


/**
 * 엑셀 다운로드 버튼 클릭 이벤트
 */
scwin.btn_excel_download_onclick = function(e) {
    // 프로젝트가 선택되지 않은 경우
    if (!scwin.SELECTED_PROJECT_ID) {
        $c.win.alert("프로젝트를 선택해주세요.");
        return;
    }

    // 데이터가 없는 경우
    var totalCount = (scwin.waitingPageInfo ? scwin.waitingPageInfo.totalCount : 0) +
                    (scwin.processingPageInfo ? scwin.processingPageInfo.totalCount : 0) +
                    (scwin.completedPageInfo ? scwin.completedPageInfo.totalCount : 0);

    if (totalCount === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 엑셀 다운로드 실행
    scwin.downloadExcel();
};

/**
 * 엑셀 다운로드 실행
 */
scwin.downloadExcel = function() {
    try {
        console.log("=== 엑셀 다운로드 시작 ===");

        // 모든 데이터 합치기
        var allData = [];

        // 대기 데이터 추가
        if (scwin.waitingPageInfo && scwin.waitingPageInfo.data) {
            allData = allData.concat(scwin.waitingPageInfo.data);
        }

        // 진행중 데이터 추가
        if (scwin.processingPageInfo && scwin.processingPageInfo.data) {
            allData = allData.concat(scwin.processingPageInfo.data);
        }

        // 완료 데이터 추가
        if (scwin.completedPageInfo && scwin.completedPageInfo.data) {
            allData = allData.concat(scwin.completedPageInfo.data);
        }

        console.log("총 다운로드 데이터 수:", allData.length);

        if (allData.length === 0) {
            $c.win.alert("다운로드할 데이터가 없습니다.");
            return;
        }

        // 엑셀 데이터 변환
        var excelData = scwin.convertToExcelData(allData);

        // 파일명 생성
        var fileName = scwin.generateExcelFileName();

        // 엑셀 다운로드 실행
        scwin.executeExcelDownload(excelData, fileName);

        console.log("=== 엑셀 다운로드 완료 ===");

    } catch (error) {
        console.error("엑셀 다운로드 실패:", error);
        $c.win.alert("엑셀 다운로드 중 오류가 발생했습니다.");
    }
};

/**
 * 데이터를 엑셀 형식으로 변환
 * @param {Array} data - 원본 데이터
 * @returns {Array} 엑셀용 데이터
 */
scwin.convertToExcelData = function(data) {
    var excelData = [];

    // 헤더 추가
    var headers = [
        "번호",
        "프로젝트명", 
        "이슈/리스크명",
        "작성자",
        "상태",
        "우선순위",
        "완료예정일",
        "해결일",
        "등록일시",
        "수정일시"
    ];
    excelData.push(headers);

    // 데이터 추가
    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        var row = [
            i + 1, // 번호
            item.pjtName || "", // 프로젝트명
            item.name || "", // 이슈/리스크명
            item.userName || "", // 작성자
            scwin.getStatusText(item.status), // 상태
            scwin.getPriorityText(item.priority), // 우선순위
            scwin.formatDate(item.dueDate), // 완료예정일
            scwin.formatDate(item.resolvedDate), // 해결일
            scwin.formatDateTime(item.createdAt), // 등록일시
            scwin.formatDateTime(item.updatedAt) // 수정일시
        ];
        excelData.push(row);
    }

    return excelData;
};

/**
 * 상태 코드를 텍스트로 변환
 * @param {string} status - 상태 코드
 * @returns {string} 상태 텍스트
 */
scwin.getStatusText = function(status) {
    switch(status) {
        case "PEN": return "대기";
        case "IPR": return "진행중";
        case "COM": return "완료";
        default: return status || "";
    }
};

/**
 * 우선순위 코드를 텍스트로 변환
 * @param {string} priority - 우선순위 코드
 * @returns {string} 우선순위 텍스트
 */
scwin.getPriorityText = function(priority) {
    switch(priority) {
        case "CR": return "우선";
        case "HI": return "높음";
        case "MD": return "중간";
        case "LO": return "낮음";
        default: return priority || "";
    }
};

/**
 * 날짜 포맷팅 (YYYY-MM-DD)
 * @param {string} dateString - 날짜 문자열
 * @returns {string} 포맷된 날짜
 */
scwin.formatDate = function(dateString) {
    if (!dateString) return "";

    try {
        // 이미 YYYY-MM-DD 형식이면 그대로 반환
        if (dateString.match(/^\d{4}-\d{2}-\d{2}$/)) {
            return dateString;
        }

        // 다른 형식이면 Date 객체로 변환 후 포맷팅
        var date = new Date(dateString);
        if (isNaN(date.getTime())) return dateString;

        var year = date.getFullYear();
        var month = String(date.getMonth() + 1).padStart(2, '0');
        var day = String(date.getDate()).padStart(2, '0');

        return year + '-' + month + '-' + day;
    } catch (e) {
        return dateString;
    }
};

/**
 * 날짜시간 포맷팅 (YYYY-MM-DD HH:mm:ss)
 * @param {string} dateTimeString - 날짜시간 문자열
 * @returns {string} 포맷된 날짜시간
 */
scwin.formatDateTime = function(dateTimeString) {
    if (!dateTimeString) return "";

    try {
        // 이미 YYYY-MM-DD HH:mm:ss 형식이면 그대로 반환
        if (dateTimeString.match(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)) {
            return dateTimeString;
        }

        // 다른 형식이면 Date 객체로 변환 후 포맷팅
        var date = new Date(dateTimeString);
        if (isNaN(date.getTime())) return dateTimeString;

        var year = date.getFullYear();
        var month = String(date.getMonth() + 1).padStart(2, '0');
        var day = String(date.getDate()).padStart(2, '0');
        var hours = String(date.getHours()).padStart(2, '0');
        var minutes = String(date.getMinutes()).padStart(2, '0');
        var seconds = String(date.getSeconds()).padStart(2, '0');

        return year + '-' + month + '-' + day + ' ' + hours + ':' + minutes + ':' + seconds;
    } catch (e) {
        return dateTimeString;
    }
};

/**
 * 엑셀 파일명 생성
 * @returns {string} 파일명
 */
scwin.generateExcelFileName = function() {
    var now = new Date();
    var year = now.getFullYear();
    var month = String(now.getMonth() + 1).padStart(2, '0');
    var day = String(now.getDate()).padStart(2, '0');
    var hours = String(now.getHours()).padStart(2, '0');
    var minutes = String(now.getMinutes()).padStart(2, '0');

    var dateTimeStr = year + month + day + '_' + hours + minutes;
    var projectName = scwin.SELECTED_PROJECT_NAME || "프로젝트";

    // 파일명에 사용할 수 없는 문자 제거
    projectName = projectName.replace(/[<>:"/\\|?*]/g, '');

    return "이슈리스크관리_" + projectName + "_" + dateTimeStr + ".xlsx";
};

/**
 * 실제 엑셀 다운로드 실행
 * @param {Array} data - 엑셀 데이터
 * @param {string} fileName - 파일명
 */
scwin.executeExcelDownload = function(data, fileName) {
    try {
        // WebSquare의 유틸리티 함수 사용 (만약 있다면)
        if (typeof $c.util.exportExcel === 'function') {
            $c.util.exportExcel(data, fileName);
            return;
        }

        // 대체 방법: CSV 형식으로 다운로드
        scwin.downloadAsCSV(data, fileName.replace('.xlsx', '.csv'));

    } catch (error) {
        console.error("엑셀 다운로드 실행 실패:", error);
        // 마지막 대안: JSON 형태로 다운로드
        scwin.downloadAsJSON(data, fileName.replace('.xlsx', '.json'));
    }
};

/**
 * CSV 형식으로 다운로드
 * @param {Array} data - 데이터
 * @param {string} fileName - 파일명
 */
scwin.downloadAsCSV = function(data, fileName) {
    var csvContent = '';

    for (var i = 0; i < data.length; i++) {
        var row = data[i];
        var csvRow = '';

        for (var j = 0; j < row.length; j++) {
            var cell = String(row[j] || '');
            // CSV에서 특수문자 처리
            if (cell.indexOf(',') !== -1 || cell.indexOf('"') !== -1 || cell.indexOf('\n') !== -1) {
                cell = '"' + cell.replace(/"/g, '""') + '"';
            }
            csvRow += cell;
            if (j < row.length - 1) csvRow += ',';
        }

        csvContent += csvRow + '\n';
    }

    // BOM 추가 (한글 깨짐 방지)
    var bom = '\uFEFF';
    var blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });

    scwin.downloadBlob(blob, fileName);
};

/**
 * JSON 형식으로 다운로드
 * @param {Array} data - 데이터
 * @param {string} fileName - 파일명
 */
scwin.downloadAsJSON = function(data, fileName) {
    var jsonContent = JSON.stringify(data, null, 2);
    var blob = new Blob([jsonContent], { type: 'application/json;charset=utf-8;' });

    scwin.downloadBlob(blob, fileName);
};

/**
 * Blob 파일 다운로드
 * @param {Blob} blob - 다운로드할 Blob
 * @param {string} fileName - 파일명
 */
scwin.downloadBlob = function(blob, fileName) {
    try {
        if (window.navigator && window.navigator.msSaveOrOpenBlob) {
            // IE 지원
            window.navigator.msSaveOrOpenBlob(blob, fileName);
        } else {
            // 다른 브라우저
            var link = document.createElement('a');
            link.href = window.URL.createObjectURL(blob);
            link.download = fileName;
            link.style.display = 'none';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            window.URL.revokeObjectURL(link.href);
        }

        console.log("파일 다운로드 완료:", fileName);

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        $c.win.alert("파일 다운로드에 실패했습니다.");
    }
};

